import { inject, Injectable } from "@angular/core";
import { Conditional, SuperService } from "./super.service";
import { AdvancedSearchFilter } from "../shared/tabla/tabla.component";
import { Tramite, TramiteStatus } from "../models/tramite";
import { LocalStorageService } from "../services/localStorage/local-storage.service";

@Injectable({
    providedIn: 'root'
})
export class TramiteService extends SuperService<Tramite> {
    protected model = 'tramites';
    protected columns: (keyof Tramite)[] = [
        'tipo',
        'empresa_id',
        'empresa_vinculada_id',
        'proyecto_inversion_id',
        'usuario_id',
        'deleted_at',
        'created_at',
        'updated_at'
    ];
    private localStorageService = inject(LocalStorageService);

    public async usuarioLogeadoTieneTramite() {
        const user = this.localStorageService.getUser();

        if (!user || user.user.user_type !== 'EXTERNO') {
            return false;
        }

        const tramites = await this.all({ usuario_id: user.user.id });
        return tramites.length > 0;
    }

    public async getCurrentTramite(withRelations: string[] = []) {
        const user = this.localStorageService.getUser();

        if (!user || user.user.user_type !== 'EXTERNO') {
            return;
        }

        const tramites = await this.all({
            conditionals: { usuario_id: user.user.id, deleted_at: null },
            relations: withRelations,
            loader: false,
        });

        return tramites[0];
    }

    public async marcarComoRecibida(tramiteId: number) {
        const response = await this.update(tramiteId, { status: 'RECIBIDA' });

        if (!response?.status) {
            throw new Error('Error al marcar como recibido');
        }

        return response;
    }

    public async getTramites(
        page = 1,
        perPage = 20,
        filters?: { empresaNombre?: string; tramiteId?: string }
    ) {
        const conditionals: Conditional[] = [
            { key: 'deleted_at', operator: 'IS NULL', value: null }
        ];

        const advancedSearch: AdvancedSearchFilter[] = [];

        if (filters?.empresaNombre && filters.empresaNombre.trim() !== '') {
            const nombre = filters.empresaNombre.trim();

            advancedSearch.push({
                relation: 'empresa',
                conditionals: [['nombre_solicitante', 'LIKE', nombre]],
                andConditionals: [],
            });

            advancedSearch.push({
                relation: 'empresaVinculada',
                conditionals: [['nombre_solicitante', 'LIKE', nombre]],
                andConditionals: [],
                opWhere: 'OR' as unknown as boolean,
            });
        }

        if (filters?.tramiteId && filters.tramiteId.trim() !== '') {
            conditionals.push({
                key: 'id',
                operator: '=',
                value: parseInt(filters.tramiteId, 10)
            });
        }

        return this.get(
            {
                conditionals,
                advancedSearch,
                paginator: {
                    page,
                    per_page: perPage,
                    sort: { column: 'created_at', desc: true }
                }
            },
            ['empresa', 'empresaVinculada', 'usuario', 'tramiteDocumentos', 'proyectoInversion'],
            true
        );
    }

    public async updateTramiteStatus(tramiteId: number | undefined, status: TramiteStatus) {
        if (!tramiteId) {
            return false;
        }
        const response = await this.update(tramiteId, { status });
        return response.status;
    }
}